Running command: cd /workspace/repo-vul/src-vul/openssl && python - <<'PY'
from pathlib import Path
p=Path('fuzz/client.c')
s=p.read_text()
# add minimal PSK callback to force PSK-family path if possible
insert='''
static unsigned int psk_client_cb(SSL *ssl, const char *hint, char *identity,
                                  unsigned int max_identity_len,
                                  unsigned char *psk, unsigned int max_psk_len) {
    const char *id = "client";
    const unsigned char key[] = "0123456789abcdef";
    size_t id_len = strlen(id);
    if (id_len + 1 > max_identity_len || sizeof(key) - 1 > max_psk_len)
        return 0;
    memcpy(identity, id, id_len + 1);
    memcpy(psk, key, sizeof(key) - 1);
    return sizeof(key) - 1;
}
'''
if 'static unsigned int psk_client_cb' not in s:
    s=s.replace('#include <openssl/ssl.h>\n', '#include <openssl/ssl.h>\n#include <string.h>\n'+insert+'\n')
# set PSK ciphers
s=s.replace('    OPENSSL_assert(SSL_set_cipher_list(client, "DHE-RSA-AES128-SHA:DHE-RSA-AES256-SHA:ADH-AES128-SHA:ADH-AES256-SHA") == 1);\n','    OPENSSL_assert(SSL_set_cipher_list(client, "PSK-AES128-CBC-SHA:PSK-AES256-CBC-SHA:DHE-RSA-AES128-SHA") == 1);\n')
# add callback
if 'SSL_set_psk_client_callback(client, psk_client_cb);' not in s:
    s=s.replace('    SSL_set_verify(client, SSL_VERIFY_NONE, NULL);\n', '    SSL_set_verify(client, SSL_VERIFY_NONE, NULL);\n    SSL_set_psk_client_callback(client, psk_client_cb);\n')
p.write_text(s)
print('patched psk')
PY
sed -n '1,70p' fuzz/client.c && echo '---' && sed -n '72,96p' fuzz/client.c

